import React, { useEffect, useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import API from "../api/axiosConfig";
import Navbar from "./components/Navbar";
import "./ProductList.css";

const PAGE_SIZE = 10;

const ProductList = () => {
  const navigate = useNavigate();

  // ── State ────────────────────────────────────────────────────────────────────
  const [products, setProducts] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [categoryFilter, setCategoryFilter] = useState("All");
  const [sortConfig, setSortConfig] = useState({ key: "name", direction: "asc" });
  const [currentPage, setCurrentPage] = useState(1);
  const [deleteId, setDeleteId] = useState(null);

  // ── Fetch products ───────────────────────────────────────────────────────────
  const fetchProducts = useCallback(async () => {
    setLoading(true);
    setErrorMsg("");
    try {
      const { data } = await API.get("/products");
      setProducts(data);
    } catch (err) {
      setErrorMsg("Could not load products. Check your connection.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchProducts();
  }, [fetchProducts]);

  // ── Filter + Sort ────────────────────────────────────────────────────────────
  useEffect(() => {
    let list = [...products];

    if (categoryFilter !== "All") {
      list = list.filter((p) => p.category === categoryFilter);
    }

    if (searchTerm.trim()) {
      const term = searchTerm.toLowerCase();
      list = list.filter(
        (p) =>
          p.name.toLowerCase().includes(term) ||
          p.sku.toLowerCase().includes(term) ||
          p.location?.toLowerCase().includes(term)
      );
    }

    list.sort((a, b) => {
      const aVal = a[sortConfig.key] ?? "";
      const bVal = b[sortConfig.key] ?? "";
      if (aVal < bVal) return sortConfig.direction === "asc" ? -1 : 1;
      if (aVal > bVal) return sortConfig.direction === "asc" ? 1 : -1;
      return 0;
    });

    setFiltered(list);
    setCurrentPage(1);
  }, [products, searchTerm, categoryFilter, sortConfig]);

  // ── Pagination ───────────────────────────────────────────────────────────────
  const totalPages = Math.ceil(filtered.length / PAGE_SIZE);
  const paginated = filtered.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE
  );

  // ── Sort handler ─────────────────────────────────────────────────────────────
  const handleSort = (key) => {
    setSortConfig((prev) =>
      prev.key === key
        ? { key, direction: prev.direction === "asc" ? "desc" : "asc" }
        : { key, direction: "asc" }
    );
  };

  const sortIcon = (key) => {
    if (sortConfig.key !== key) return " ⇅";
    return sortConfig.direction === "asc" ? " ↑" : " ↓";
  };

  // ── Delete ───────────────────────────────────────────────────────────────────
  const confirmDelete = (id) => setDeleteId(id);
  const cancelDelete = () => setDeleteId(null);

  const handleDelete = async () => {
    try {
      await API.delete(`/products/${deleteId}`);
      setProducts((prev) => prev.filter((p) => p.id !== deleteId));
    } catch {
      setErrorMsg("Delete failed. Please try again.");
    } finally {
      setDeleteId(null);
    }
  };

  // ── Unique categories ────────────────────────────────────────────────────────
  const categories = ["All", ...new Set(products.map((p) => p.category).filter(Boolean))];

  // ── Stock badge ──────────────────────────────────────────────────────────────
  const stockBadge = (qty) => {
    if (qty === 0) return <span className="badge badge-red">Out of stock</span>;
    if (qty < 10) return <span className="badge badge-yellow">Low stock</span>;
    return <span className="badge badge-green">In stock</span>;
  };

  // ── Render ───────────────────────────────────────────────────────────────────
  return (
    <>
      <Navbar />
      <div className="page-container">
        <div className="list-header">
          <h2 className="form-title">Product Inventory</h2>
          <button className="btn-primary" onClick={() => navigate("/add-product")}>
            + Add Product
          </button>
        </div>

        {/* Controls */}
        <div className="controls-row">
          <input
            className="search-input"
            type="text"
            placeholder="Search by name, SKU or location…"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          <select
            className="filter-select"
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
          >
            {categories.map((c) => (
              <option key={c}>{c}</option>
            ))}
          </select>
          <button className="btn-secondary" onClick={fetchProducts}>
            Refresh
          </button>
        </div>

        {errorMsg && <div className="alert alert-error">{errorMsg}</div>}

        {/* Table */}
        {loading ? (
          <div className="loading-state">Loading inventory…</div>
        ) : paginated.length === 0 ? (
          <div className="empty-state">
            <p>No products found.</p>
            <button className="btn-primary" onClick={() => navigate("/add-product")}>
              Add your first product
            </button>
          </div>
        ) : (
          <>
            <div className="table-wrapper">
              <table className="product-table">
                <thead>
                  <tr>
                    <th onClick={() => handleSort("name")}>Name{sortIcon("name")}</th>
                    <th onClick={() => handleSort("sku")}>SKU{sortIcon("sku")}</th>
                    <th onClick={() => handleSort("category")}>Category{sortIcon("category")}</th>
                    <th onClick={() => handleSort("location")}>Location{sortIcon("location")}</th>
                    <th onClick={() => handleSort("quantity")}>Qty{sortIcon("quantity")}</th>
                    <th onClick={() => handleSort("price")}>Price{sortIcon("price")}</th>
                    <th>Status</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paginated.map((product) => (
                    <tr key={product.id}>
                      <td className="td-name">{product.name}</td>
                      <td className="td-mono">{product.sku}</td>
                      <td>{product.category}</td>
                      <td className="td-mono">{product.location}</td>
                      <td className="td-center">{product.quantity}</td>
                      <td className="td-center">₹{Number(product.price).toFixed(2)}</td>
                      <td>{stockBadge(product.quantity)}</td>
                      <td className="td-actions">
                        <button
                          className="btn-icon btn-edit"
                          title="Edit"
                          onClick={() => navigate(`/edit-product/${product.id}`)}
                        >
                          ✏️
                        </button>
                        <button
                          className="btn-icon btn-delete"
                          title="Delete"
                          onClick={() => confirmDelete(product.id)}
                        >
                          🗑️
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>

            {/* Pagination */}
            <div className="pagination">
              <button
                className="btn-secondary"
                onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))}
                disabled={currentPage === 1}
              >
                ← Prev
              </button>
              <span className="page-info">
                Page {currentPage} of {totalPages} &nbsp;·&nbsp; {filtered.length} items
              </span>
              <button
                className="btn-secondary"
                onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))}
                disabled={currentPage === totalPages}
              >
                Next →
              </button>
            </div>
          </>
        )}
      </div>

      {/* Delete Confirmation Modal */}
      {deleteId && (
        <div className="modal-overlay">
          <div className="modal">
            <h3>Delete Product?</h3>
            <p>This action cannot be undone.</p>
            <div className="modal-actions">
              <button className="btn-secondary" onClick={cancelDelete}>Cancel</button>
              <button className="btn-danger" onClick={handleDelete}>Delete</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ProductList;
